630	    fn hex_of(bytes: &[u8]) -> String {
631	        let mut s = String::with_capacity(bytes.len() * 2);
632	        for b in bytes {
633	            write!(s, "{b:02X}").unwrap();
634	        }
635	        s
636	    }
