696	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
697	    /// multi-valued RDNs joined with '+'). Values of known attribute types
698	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
699	    /// when their tag has a text decoder; a known type carrying any other
700	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
701	    /// name and uses the '#' form carrying the value's full DER encoding in
702	    /// hex. Attributes without a known short name use their dotted OID with
703	    /// the same '#' form.
704	    ///
705	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
706	    /// encodings must be sorted by their full encoding bytes (tag, then
707	    /// length, then content — the encoding, never the display name, dotted
708	    /// OID text or decoded value). The check is per RDN; it never reorders
709	    /// the members itself. `what` names the name being checked ("subject" or
710	    /// "issuer") so an ordering failure identifies it in the error message.
711	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
712	        let mut rdn_buf = name.content;
713	        let mut rdns: Vec<String> = Vec::new();
714	        while !rdn_buf.is_empty() {
715	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
716	            rdn_buf = rest;
717	
718	            let mut atv_buf = set.content;
719	            let mut parts = Vec::new();
720	            // Raw full encoding (tag, length and content) of each member of
721	            // this SET OF, straight from the certificate: DER SET OF ordering
722	            // compares the complete member encodings byte for byte. Equal
723	            // encodings may legitimately repeat and stay adjacent.
724	            let mut members: Vec<&[u8]> = Vec::new();
725	            while !atv_buf.is_empty() {
726	                let atv_start = atv_buf;
727	                let (atv, rest) =
728	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
729	                atv_buf = rest;
730	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
731	
732	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
733	                let (value, after_value) = read_tlv(after_oid)?;
734	                if !after_value.is_empty() {
735	                    return Err("trailing data in attribute value".to_string());
736	                }
737	
738	                let oid_arcs = parse_oid(oid.content)?;
739	
740	                // The value's own string-type rules are applied exactly once,
741	                // here, before any display decision and regardless of whether
742	                // the attribute later renders as text for a known short name
743	                // or as '#'-hex for an unknown type: a UTF8String must hold
744	                // valid UTF-8, a PrintableString must keep to its alphabet, a
745	                // BMPString must hold whole 16-bit non-surrogate characters
746	                // and a UniversalString must hold whole, in-range Unicode
747	                // code points. The hex form must never let an illegal byte or
748	                // code point through, and illegal content cannot be dropped or
749	                // replaced. An empty value stays legal. Tags without string
750	                // rules (SEQUENCE, OCTET STRING, ...) pass untouched and are
751	                // simply not text-decodable. `what` names the offending name
752	                // ("subject"/"issuer").
753	                let text = check_attribute_string(value, what)?;
754	
755	                match oid_short_name(&oid_arcs) {
756	                    Some(label) => match text {
757	                        // Supported string type: decode to escaped text.
758	                        Some(text) => parts.push(format!("{label}={}", escape_value(&text))),
759	                        // Known type but a legal value with no text decoder
760	                        // (SEQUENCE, OCTET STRING, ...): keep the short name
761	                        // and show the full original DER encoding as '#'-hex.
762	                        None => {
763	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)))
764	                        }
765	                    },
766	                    None => {
767	                        // Unknown attribute type: RFC 4514 requires the form
768	                        // OID=#hex, where the hex is the full DER encoding
769	                        // (tag, length and content) of the attribute value.
770	                        // The value is still a string governed by its type
771	                        // rules, already checked once above; whether it
772	                        // decoded to text never affects this hex display.
773	                        let hex = value_hex(after_oid, after_value);
774	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
775	                    }
776	                }
777	            }
778	            if parts.is_empty() {
779	                return Err("empty RelativeDistinguishedName".to_string());
780	            }
781	            check_rdn_der_order(&members, what)?;
782	            rdns.push(parts.join("+"));
783	        }
784	        rdns.reverse();
785	        Ok(rdns.join(","))
786	    }
