788	    /// Validate one RDN as a DER SET OF: every member's complete
789	    /// AttributeTypeAndValue encoding must be less than or equal to the next
790	    /// one under ordinary byte ordering of tag, length and content. The
791	    /// comparison runs on the raw encodings only — CN/O short names, dotted
792	    /// OID text and decoded values never enter into it — and equal adjacent
793	    /// members (duplicate attributes) are allowed. The members are never
794	    /// reordered to make an unsorted input pass. `what` is "subject" or
795	    /// "issuer" and identifies the offending name in the error message.
796	    fn check_rdn_der_order(members: &[&[u8]], what: &str) -> Result<(), String> {
797	        for pair in members.windows(2) {
798	            if pair[0] > pair[1] {
799	                return Err(format!(
800	                    "{what} name: attributes of a multi-valued RelativeDistinguishedName \
801	                     are not encoded in DER SET OF order (the members must be sorted by \
802	                     their complete DER encoding bytes: tag, then length, then content)"
803	                ));
804	            }
805	        }
806	        Ok(())
807	    }
