822	    /// One OID arc (subidentifier) as an arbitrary-precision unsigned
823	    /// integer. An OID arc has no upper bound in the standard: any
824	    /// shortest-form base-128 subidentifier is legal, however many bits its
825	    /// value needs, so the arcs are kept as exact bignums rather than a
826	    /// machine integer whose range would become a false legality limit.
827	    ///
828	    /// `limbs` is little-endian base 2^32 with no trailing zero limbs; the
829	    /// empty vector is zero. Normalization is maintained by every
830	    /// constructor and mutator, so derived equality is value equality.
831	    #[derive(Clone, PartialEq, Eq)]
832	    struct Arc {
833	        limbs: Vec<u32>,
834	    }
835	
836	    impl Arc {
837	        fn from_u64(value: u64) -> Arc {
838	            let mut limbs = vec![value as u32, (value >> 32) as u32];
839	            while limbs.last() == Some(&0) {
840	                limbs.pop();
841	            }
842	            Arc { limbs }
843	        }
844	
845	        /// The value as a `u64` when it fits, else `None`. Used only where a
846	        /// small arc is required (the first subidentifier split and the
847	        /// known-attribute table); large arcs simply take the other branch.
848	        fn as_u64(&self) -> Option<u64> {
849	            match self.limbs.len() {
850	                0 => Some(0),
851	                1 => Some(self.limbs[0] as u64),
852	                2 => Some(self.limbs[0] as u64 | (self.limbs[1] as u64) << 32),
853	                _ => None,
854	            }
855	        }
856	
857	        /// self = self * 128 + add (add < 128): one base-128 digit appended
858	        /// while reading a subidentifier.
859	        fn mul_add_128(&mut self, add: u32) {
860	            let mut carry = add as u64;
861	            for limb in &mut self.limbs {
862	                let t = (*limb as u64) * 128 + carry;
863	                *limb = t as u32;
864	                carry = t >> 32;
865	            }
866	            while carry > 0 {
867	                self.limbs.push(carry as u32);
868	                carry >>= 32;
869	            }
870	        }
871	
872	        /// self = self - sub, where sub < 2^32 and self >= sub. Only used to
873	        /// peel 40/80 off the first subidentifier once it is known to be
874	        /// large enough.
875	        fn sub_u32(&mut self, sub: u32) {
876	            let mut borrow = sub as u64;
877	            for limb in &mut self.limbs {
878	                let cur = *limb as u64;
879	                if cur >= borrow {
880	                    *limb = (cur - borrow) as u32;
881	                    borrow = 0;
882	                    break;
883	                }
884	                *limb = (cur + (1u64 << 32) - borrow) as u32;
885	                borrow = 1;
886	            }
887	            debug_assert_eq!(borrow, 0, "sub_u32 underflow");
888	            while self.limbs.last() == Some(&0) {
889	                self.limbs.pop();
890	            }
891	        }
892	
893	        /// Exact decimal rendering, by repeated division by 10^9.
894	        fn to_decimal(&self) -> String {
895	            if self.limbs.is_empty() {
896	                return "0".to_string();
897	            }
898	            const CHUNK: u64 = 1_000_000_000;
899	            let mut limbs = self.limbs.clone();
900	            let mut chunks: Vec<u32> = Vec::new();
901	            while !limbs.is_empty() {
902	                let mut rem = 0u64;
903	                for limb in limbs.iter_mut().rev() {
904	                    let cur = (rem << 32) | (*limb as u64);
905	                    *limb = (cur / CHUNK) as u32;
906	                    rem = cur % CHUNK;
907	                }
908	                while limbs.last() == Some(&0) {
909	                    limbs.pop();
910	                }
911	                chunks.push(rem as u32);
912	            }
913	            let mut s = chunks.last().unwrap().to_string();
914	            for chunk in chunks.iter().rev().skip(1) {
915	                write!(s, "{chunk:09}").unwrap();
916	            }
917	            s
918	        }
919	    }
