1159	            }
1160	            // NumericString (0x12), IA5String (0x16) and VisibleString (0x1A)
1161	            // are ASCII-family strings: every byte is also its Unicode code
1162	            // point and they carry no extra character rule here.
1163	            0x12 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
1164	            // T.61/TeletexString (0x14) and GeneralString (0x1B) are
1165	            // conventionally treated as Latin-1 here: the byte value is the
1166	            // code point and they carry no extra character rule here.
1167	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
1168	            TAG_BMP_STRING => decode_bmp_string(content, what)?,
1169	            TAG_UNIVERSAL_STRING => decode_universal_string(content, what)?,
1170	            // Any other readable DER value (SEQUENCE, OCTET STRING, ...) is a
1171	            // legal non-text attribute value: it has no string rule to apply
1172	            // and no text decoder, so it is rendered from its original DER as
1173	            // '#'-hex.
1174	            _ => return Ok(None),
1175	        };
1176	        Ok(Some(text))
1177	    }
