1	//! End-to-end regression tests for the name (Subject/Issuer) decoding and
2	//! display behavior documented in README.md.
3	//!
4	//! These tests drive the real `chainview` binary so the public contract is
5	//! locked as a whole: the five output lines and their order on success, and
6	//! exit code 2 with empty stdout plus the `chainview: invalid DER
7	//! certificate:` stderr prefix on malformed input. Only name decoding is
8	//! exercised — signature verification, trust and expiry are intentionally out
9	//! of scope.
10	//!
11	//! Certificates are built with the tiny zero-dependency DER constructor at the
12	//! bottom of this file, which lets individual name components (including
13	//! truncated or non-minimal value encodings) be crafted byte for byte.
14	
15	use std::fs;
16	use std::path::PathBuf;
17	use std::process::{Command, Output};
18	use std::sync::atomic::{AtomicU64, Ordering};
19	
20	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
21	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
22	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
23	
24	// ----- Known X.520 attribute OID arcs -------------------------------------
25	
26	const CN: &[u64] = &[2, 5, 4, 3];
27	const O: &[u64] = &[2, 5, 4, 10];
28	const C: &[u64] = &[2, 5, 4, 6];
29	const POSTAL_ADDRESS: &[u64] = &[2, 5, 4, 17];
30	const POSTAL_CODE: &[u64] = &[2, 5, 4, 18];
31	
32	// The spec example: a SEQUENCE containing only UTF8String "abc", with its
33	// complete DER encoding.
34	const POSTAL_ADDRESS_ABC_HEX: &str = "30050C03616263";
35	
36	// ----- Success cases -------------------------------------------------------
37	
38	#[test]
39	fn unknown_oid_uses_dotted_oid_and_full_der_hex() {
40	    // The exact README example: UTF8String "abc" for type 1.2.3.4 must render
41	    // as 1.2.3.4=#0C03616263 — tag, length and content, readable text or not.
42	    let subject = name(&[rdn(&[atv_utf8(&[1, 2, 3, 4], "abc")])]);
43	    let issuer = simple_cn_name("Test CA");
44	    let (out, _cert) = run_inspect("unknown-basic", &build_cert(&subject, &issuer));
45	
46	    assert_success(
47	        &out,
48	        "1.2.3.4=#0C03616263",
49	        "CN=Test CA",
50	    );
51	}
52	
53	#[test]
54	fn unknown_oid_value_preserves_long_form_length() {
55	    // A 128-byte content needs the long-form length 0x81 0x80; the hex must
56	    // carry the original TLV header verbatim instead of collapsing the length
57	    // or emitting only the content bytes.
58	    let long_text = "a".repeat(128);
59	    let subject = name(&[rdn(&[atv_utf8(&[1, 2, 3, 4], &long_text)])]);
60	    let issuer = simple_cn_name("Test CA");
61	    let (out, _cert) = run_inspect("unknown-longlen", &build_cert(&subject, &issuer));
62	
63	    let mut expected_hex = String::from("0C8180");
64	    expected_hex.push_str(&"61".repeat(128));
65	    assert_success(&out, &format!("1.2.3.4=#{expected_hex}"), "CN=Test CA");
66	}
67	
68	#[test]
69	fn unknown_oid_under_2_999_keeps_numeric_arcs() {
70	    // 2.999.* is a legal OID whose first subidentifier (1079) needs multiple
71	    // base-128 bytes (0x88 0x37); it must stay a dotted decimal identifier.
72	    let subject = name(&[rdn(&[atv_utf8(&[2, 999, 1], "x")])]);
73	    let issuer = simple_cn_name("Test CA");
74	    let (out, _cert) = run_inspect("unknown-2999", &build_cert(&subject, &issuer));
75	
76	    assert_success(&out, "2.999.1=#0C0178", "CN=Test CA");
77	}
78	
79	#[test]
80	fn unknown_non_string_value_is_shown_as_full_der_hex() {
81	    // An OCTET STRING value (tag 0x04) is not text at all; the full encoding
82	    // still appears after '#'.
83	    let value = tlv(0x04, &[0x01, 0x02, 0x03]);
84	    let subject = name(&[rdn(&[atv(&[1, 2, 3, 4], &value)])]);
85	    let issuer = simple_cn_name("Test CA");
86	    let (out, _cert) = run_inspect("unknown-octet", &build_cert(&subject, &issuer));
87	
88	    assert_success(&out, "1.2.3.4=#0403010203", "CN=Test CA");
89	}
90	
91	#[test]
92	fn mixed_known_and_unknown_attributes_keep_their_own_forms() {
93	    // Encoded RDN order (display is reversed):
94	    //   SET { C=CN }
95	    //   SET { O=示例公司 }
96	    //   SET { 1.2.3.4 "abc", 1.2.3.4 "def", CN=example.com }
97	    // The last SET is one multi-valued RDN: joined with '+', never split into
98	    // groups; the repeated unknown attribute appears twice (never merged); the
99	    // adjacent CN stays text; CJK content passes through as raw UTF-8; groups
100	    // are shown in reverse order; '#' is the encoding marker, unescaped. The
101	    // members within the SET are listed in DER SET OF byte order: the two
102	    // unknown attributes (shorter complete encodings than CN) sort first,
103	    // then CN, and the duplicate unknown members stay adjacent in their own
104	    // ascending order — display preserves that encoding order verbatim.
105	    let subject = name(&[
106	        rdn(&[atv_utf8(C, "CN")]),
107	        rdn(&[atv_utf8(O, "示例公司")]),
108	        rdn(&[
109	            atv_utf8(&[1, 2, 3, 4], "abc"),
110	            atv_utf8(&[1, 2, 3, 4], "def"),
111	            atv_utf8(CN, "example.com"),
112	        ]),
113	    ]);
114	    let issuer = simple_cn_name("Test CA");
115	    let (out, _cert) = run_inspect("mixed", &build_cert(&subject, &issuer));
116	
117	    assert_success(
118	        &out,
119	        "1.2.3.4=#0C03616263+1.2.3.4=#0C03646566+CN=example.com,O=示例公司,C=CN",
120	        "CN=Test CA",
121	    );
122	}
123	
124	#[test]
125	fn subject_and_issuer_render_independently() {
126	    // Each name reflects only its own attributes: distinct OID sets and value
127	    // encodings must never bleed across Subject/Issuer.
128	    let subject = name(&[
129	        rdn(&[atv_utf8(O, "测试")]),
130	        rdn(&[atv_utf8(CN, "subject.example")]),
131	    ]);
132	    // The issuer's multi-valued RDN follows DER SET OF order: the unknown
133	    // attribute's complete encoding is shorter, so it sorts before CN even
134	    // though CN would come first as a displayed name; display keeps the
135	    // encoding order.
136	    let issuer = name(&[rdn(&[
137	        atv_utf8(&[1, 2, 3, 4], "abc"),
138	        atv_utf8(CN, "Example CA"),
139	    ])]);
140	    let (out, _cert) = run_inspect("separate-names", &build_cert(&subject, &issuer));
141	
142	    assert_success(
143	        &out,
144	        "CN=subject.example,O=测试",
145	        "1.2.3.4=#0C03616263+CN=Example CA",
146	    );
147	}
