164	#[test]
165	fn known_non_string_value_applies_to_issuer_as_well() {
166	    // The same rule independently governs the Issuer name.
167	    let subject = simple_cn_name("subject.example");
168	    let issuer = name(&[
169	        rdn(&[atv(POSTAL_ADDRESS, &seq(&tlv(0x0C, b"abc")))]),
170	        rdn(&[atv_utf8(CN, "Test CA")]),
171	    ]);
172	    let (out, _cert) = run_inspect("known-sequence-issuer", &build_cert(&subject, &issuer));
173	
174	    assert_success(&out, "CN=subject.example", "CN=Test CA,postalAddress=#30050C03616263");
175	}
