177	#[test]
178	fn known_non_string_value_preserves_long_form_length() {
179	    // A legal long-form length in the value TLV must be carried byte for byte
180	    // after '#', not collapsed and not rebuilt from the parsed content.
181	    let value = tlv(0x04, &vec![0x41u8; 128]); // postalCode as OCTET STRING
182	    let subject = name(&[rdn(&[atv(POSTAL_CODE, &value)])]);
183	    let issuer = simple_cn_name("Test CA");
