224	fn known_attribute_with_bad_string_is_still_rejected_not_hexified() {
225	    // A supported string type that fails to decode must never be salvaged by
226	    // the hex fallback: invalid UTF-8 in a known attribute is still corrupt.
227	    let bad_value = tlv(0x0C, &[0xFF, 0xFE]);
228	    let subject = name(&[rdn(&[atv(POSTAL_ADDRESS, &bad_value)])]);
229	    let issuer = simple_cn_name("Test CA");
