240	    inner.extend_from_slice(&[0x30, 0x05, 0x0C, 0x02, 0xAB]); // len 5, 4 present
241	    let subject = name(&[rdn(&[seq(&inner)])]);
242	    let issuer = simple_cn_name("Test CA");
243	    let (out, _cert) = run_inspect("known-truncated", &build_cert(&subject, &issuer));
