249	fn known_non_string_value_with_extra_field_is_rejected() {
250	    // Two value TLVs inside one AttributeTypeAndValue stay illegal even when
251	    // the first value would render as hex.
252	    let two_values = concat(&[&seq(&tlv(0x0C, b"abc")), &tlv(0x05, &[])]);
253	    let subject = name(&[rdn(&[atv(POSTAL_ADDRESS, &two_values)])]);
254	    let issuer = simple_cn_name("Test CA");
