    // replaced or stripped.
    for cp in [0xD800u32, 0xDBFF, 0xDC00, 0xDFFF] {
        let content = universal_units(&[0x0041, cp, 0x0042]);
        let subject = name(&[rdn(&[atv_universal(CN, &content)])]);
        let issuer = simple_cn_name("Test CA");
