    for cp in [0x00110000u32, 0x001FFFFF, 0x7FFFFFFF, 0xFFFFFFFF] {
        let content = universal_units(&[0x0041, cp]);
        let subject = name(&[rdn(&[atv_universal(CN, &content)])]);
