        assert_invalid_certificate(&out);
        let stderr = lossy(&out.stderr);
        assert!(
            stderr.contains("subject") && stderr.contains("UniversalString"),
            "U+{cp:04X} must fail as a subject UniversalString error: {stderr}"
        );
    }
}

