50	#[test]
51	fn complete_certificate_file_shows_the_five_fields_in_order() {
52	    // The baseline contract: a whole, legal file prints exactly Subject,
53	    // Issuer, Serial Number, Not Before, Not After — in that order — exits 0
54	    // and writes nothing to stderr.
55	    let cert = build_cert();
56	    let out = run_inspect("complete", &cert);
