60	#[test]
61	fn certificate_using_long_form_lengths_is_accepted() {
62	    // The ordinary fixed fixture already exceeds 127 bytes of content, so its
63	    // outer Certificate SEQUENCE necessarily uses a long-form length; that
64	    // must not be mistaken for extra data.
65	    let cert = build_cert();
66	    assert_eq!(
67	        &cert[..2],
68	        &[0x30, 0x81],
69	        "the fixture must genuinely carry a long-form outer length"
70	    );
71	    assert_success(&run_inspect("long-form-outer", &cert));
72	
73	    // A v3 extension with a 200-byte OCTET STRING forces an inner long-form
74	    // length (04 81 C8 ...) and pushes the certificate into a two-byte outer
75	    // length (30 82 ...): both are ordinary DER, not trailing or truncation.
76	    let value = vec![0xAAu8; 200];
77	    let ext = seq(&concat(&[&oid(UNKNOWN_OID), &tlv(0x04, &value)]));
78	    let tail = tlv(0xA3, &seq(&ext));
79	    let big = build_cert_with(Some(2), &tail, &fixed_serial(), FIXED_CN, b"260115093000Z", b"270115093000Z");
80	    assert_eq!(&big[..2], &[0x30, 0x82], "outer length should need two bytes");
81	    assert!(
82	        big.windows(3).any(|w| w == [0x04, 0x81, 0xC8]),
83	        "extension OCTET STRING should carry an inner 0x81 long-form length"
84	    );
85	    assert_success(&run_inspect("long-form-inner", &big));
86	}
