88	#[test]
89	fn interior_zero_bytes_are_not_mistaken_for_end_of_file() {
90	    // Zero bytes occur inside every normal certificate (the BIT STRING
91	    // unused-bits count, integer padding); here the serial itself carries 0x00
92	    // in its middle. Such a byte is part of the certificate and must never be
93	    // read as the end of the file.
94	    let cert = build_cert_with(
95	        Some(2),
96	        &[],
97	        &[0x10, 0x00, 0x01],
98	        FIXED_CN,
99	        b"260115093000Z",
100	        b"270115093000Z",
101	    );
102	    let out = run_inspect("inner-zero", &cert);
103	    assert_ok_fields(&out, FIXED_SUBJECT, "100001", FIXED_NOT_BEFORE, FIXED_NOT_AFTER);
104	}
