106	#[test]
107	fn interior_newline_byte_inside_a_value_is_not_mistaken_for_end_of_file() {
108	    // A UTF8String may legally contain a newline (and NUL) byte; inside the
109	    // file that byte is value content, shown under the existing escaping
110	    // rules, not a file terminator.
111	    let cert = build_cert_with(
112	        Some(2),
113	        &[],
114	        &fixed_serial(),
115	        b"a\nb\x00c",
116	        b"260115093000Z",
117	        b"270115093000Z",
118	    );
