120	    assert_ok_fields(
121	        &out,
122	        "CN=a\\0Ab\\00c",
123	        FIXED_SERIAL,
124	        FIXED_NOT_BEFORE,
125	        FIXED_NOT_AFTER,
126	    );
127	}
