372	/// Truncation failure: exit 2, empty stdout, the invalid-DER prefix and the
373	/// exact established reason wording naming the incomplete Certificate
374	/// SEQUENCE — never a success or a trailing-data report.
375	fn assert_truncated(out: &Output, expected_reason: &str) {
376	    assert_eq!(
377	        out.status.code(),
378	        Some(2),
379	        "stdout={} stderr={}",
