400	fn reason_of(out: &Output) -> String {
401	    let stderr = lossy(&out.stderr);
402	    assert!(
403	        stderr.starts_with(CERT_PREFIX),
404	        "unexpected stderr: {stderr}"
405	    );
406	    stderr.trim_end()[CERT_PREFIX.len()..].to_string()
407	}
