413	fn run_inspect(tag: &str, data: &[u8]) -> Output {
414	    let cert = TempCert::new(tag, data);
415	    Command::new(env!("CARGO_BIN_EXE_chainview"))
416	        .arg("inspect")
417	        .arg(&cert.path)
418	        .output()
419	        .expect("running chainview")
420	}
421	
422	struct TempCert {
423	    path: PathBuf,
424	}
425	
426	impl TempCert {
427	    fn new(tag: &str, data: &[u8]) -> Self {
428	        static COUNTER: AtomicU64 = AtomicU64::new(0);
429	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
430	        let path = std::env::temp_dir().join(format!(
431	            "chainview-integrity-test-{}-{tag}-{unique}.der",
432	            std::process::id()
433	        ));
434	        fs::write(&path, data).expect("writing temp certificate");
435	        TempCert { path }
436	    }
437	}
438	
439	impl Drop for TempCert {
440	    fn drop(&mut self) {
441	        let _ = fs::remove_file(&self.path);
442	    }
443	}
444	
445	// ----- Certificate / DER construction --------------------------------------
446	
447	const FIXED_CN: &[u8] = b"example.com";
448	
449	fn fixed_serial() -> Vec<u8> {
450	    vec![0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]
451	}
452	
453	/// The standard complete v3 fixture with the fixed visible fields.
454	fn build_cert() -> Vec<u8> {
455	    build_cert_with(
456	        Some(2),
457	        &[],
458	        &fixed_serial(),
459	        FIXED_CN,
460	        b"260115093000Z",
461	        b"270115093000Z",
462	    )
463	}
464	
465	fn build_cert_times(not_before: &[u8], not_after: &[u8]) -> Vec<u8> {
466	    build_cert_with(
467	        Some(2),
468	        &[],
469	        &fixed_serial(),
470	        FIXED_CN,
471	        not_before,
472	        not_after,
473	    )
474	}
475	
476	/// Assemble one complete certificate around an explicit version (`None` = v1
477	/// with no version field), an arbitrary TBS tail, and caller-chosen visible
478	/// fields so individual encodings can be crafted byte for byte.
479	#[allow(clippy::too_many_arguments)]
480	fn build_cert_with(
481	    version: Option<u8>,
482	    tail: &[u8],
483	    serial_content: &[u8],
484	    subject_cn: &[u8],
485	    not_before: &[u8],
486	    not_after: &[u8],
487	) -> Vec<u8> {
488	    let serial = tlv(0x02, serial_content);
489	    let validity = seq(&concat(&[
490	        &tlv(0x17, not_before),
491	        &tlv(0x17, not_after),
492	    ]));
493	    let subject = simple_cn_name(subject_cn);
494	    let issuer = simple_cn_name(b"Test CA");
495	    let spki = spki();
496	    let alg = signature_algorithm();
497	
498	    let mut tbs_content = Vec::new();
499	    if let Some(v) = version {
500	        tbs_content.extend_from_slice(&tlv(0xA0, &tlv(0x02, &[v])));
501	    }
502	    tbs_content.extend_from_slice(&serial);
503	    tbs_content.extend_from_slice(&alg);
504	    tbs_content.extend_from_slice(&issuer);
505	    tbs_content.extend_from_slice(&validity);
506	    tbs_content.extend_from_slice(&subject);
507	    tbs_content.extend_from_slice(&spki);
508	    tbs_content.extend_from_slice(tail);
509	    let tbs = seq(&tbs_content);
510	
511	    seq(&concat(&[
512	        &tbs,
513	        &alg,
514	        &tlv(0x03, &[0x00]),
515	    ]))
516	}
517	
518	fn signature_algorithm() -> Vec<u8> {
519	    seq(&concat(&[
520	        &oid(&[1, 2, 840, 113549, 1, 1, 11]),
521	        &tlv(0x05, &[]),
522	    ]))
523	}
524	
525	fn spki() -> Vec<u8> {
526	    let alg = seq(&concat(&[
527	        &oid(&[1, 2, 840, 113549, 1, 1, 1]),
528	        &tlv(0x05, &[]),
529	    ]));
530	    seq(&concat(&[
531	        &alg,
532	        &tlv(0x03, &[0x00, 0x01, 0x00]),
533	    ]))
534	}
535	
536	fn simple_cn_name(cn: &[u8]) -> Vec<u8> {
537	    let atv = seq(&concat(&[&oid(&[2, 5, 4, 3]), &tlv(0x0C, cn)]));
538	    let rdn = tlv(0x31, &atv);
539	    tlv(0x30, &rdn)
540	}
541	
542	/// TLV with caller-supplied length bytes; used to forge truncated encodings.
543	fn raw_tlv(tag: u8, len_bytes: &[u8], content: &[u8]) -> Vec<u8> {
544	    let mut out = vec![tag];
545	    out.extend_from_slice(len_bytes);
546	    out.extend_from_slice(content);
547	    out
548	}
549	
550	fn oid(arcs: &[u64]) -> Vec<u8> {
551	    assert!(arcs.len() >= 2);
552	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
553	    for &arc in &arcs[2..] {
554	        content.extend_from_slice(&oid_arc(arc));
555	    }
556	    tlv(0x06, &content)
557	}
558	
559	fn oid_arc(mut value: u64) -> Vec<u8> {
560	    let mut out = vec![(value % 128) as u8];
561	    value /= 128;
562	    while value > 0 {
563	        out.push(0x80 | (value % 128) as u8);
564	        value /= 128;
565	    }
566	    out.reverse();
567	    out
568	}
569	
570	fn seq(content: &[u8]) -> Vec<u8> {
571	    tlv(0x30, content)
572	}
573	
574	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
575	    let mut out = vec![tag];
576	    out.extend_from_slice(&der_len(content.len()));
577	    out.extend_from_slice(content);
578	    out
579	}
580	
581	fn der_len(n: usize) -> Vec<u8> {
582	    if n < 0x80 {
583	        vec![n as u8]
584	    } else {
585	        let mut body = Vec::new();
586	        let mut v = n;
587	        while v > 0 {
588	            body.push((v & 0xFF) as u8);
589	            v >>= 8;
590	        }
591	        body.reverse();
592	        let mut out = vec![0x80 | body.len() as u8];
593	        out.extend_from_slice(&body);
594	        out
595	    }
596	}
597	
598	fn concat(parts: &[&[u8]]) -> Vec<u8> {
599	    let mut out = Vec::new();
600	    for part in parts {
601	        out.extend_from_slice(part);
602	    }
603	    out
604	}
